  iron_warhammer: '<svg viewBox="0 0 24 24"><path d="M 12 14 L 12 22" stroke="#7a5a35" stroke-width="2" stroke-linecap="round"/><path d="M 5 6 L 19 6 L 19 14 L 5 14 Z" fill="#9aa3aa" stroke="#444" stroke-width=".7"/><path d="M 7 8 L 7 12 M 17 8 L 17 12" stroke="#666" stroke-width=".6"/><path d="M 5 6 L 8 4 L 16 4 L 19 6" fill="#888" stroke="#444" stroke-width=".6"/></svg>',

  /* ─── ARMOR ─── */
  iron_helm: '<svg viewBox="0 0 24 24"><path d="M 5 14 L 5 11 C 5 6 8 3 12 3 C 16 3 19 6 19 11 L 19 14 L 18 14 L 17 17 L 7 17 L 6 14 Z" fill="#a8b1b8" stroke="#444" stroke-width=".7"/><rect x="9" y="9" width="6" height="3" rx=".3" fill="#222"/><path d="M 11 4 L 13 4" stroke="#cdd6dc" stroke-width=".8"/></svg>',

  bronze_body: '<svg viewBox="0 0 24 24"><path d="M 6 5 L 9 4 L 12 5 L 15 4 L 18 5 L 18 9 L 16 10 L 16 19 L 8 19 L 8 10 L 6 9 Z" fill="#a8703c" stroke="#5a3a18" stroke-width=".7"/><path d="M 11 9 L 13 9 L 13 14 L 11 14 Z" fill="#7a5028"/><circle cx="12" cy="11.5" r="1" fill="#e2b84e"/></svg>',

  traveler_cape: '<svg viewBox="0 0 24 24"><path d="M 8 3 L 6 5 L 4 18 Q 4 20 6 20 L 12 19 L 18 20 Q 20 20 20 18 L 18 5 L 16 3 L 14 5 L 14 7 L 10 7 L 10 5 Z" fill="#5a4a3a" stroke="#2a2218" stroke-width=".7"/><path d="M 7 7 L 5 18 M 17 7 L 19 18" stroke="#3a2e22" stroke-width=".5"/></svg>',

