// ===== block 16: ui-overhaul-js =====
(function(){
"use strict";

/* ─── State migration ─── */
function migrate(){
  if(typeof G !== 'object' || !G) return;
  if(!G.streak || typeof G.streak !== 'object') G.streak = {count: 1, lastDay: 0};
  if(!G.dailyGoals || typeof G.dailyGoals !== 'object') G.dailyGoals = {dayKey: 0, progress: {}};
  if(typeof G.lastWelcome !== 'number') G.lastWelcome = 0;
  if(typeof G.lifetimeKills !== 'number') G.lifetimeKills = G.stats?.kills || 0;
}
[0, 100, 500, 1500].forEach(function(t){ setTimeout(migrate, t); });

/* ─── Day key (UTC) ─── */
function todayKey(){
  var d = new Date();
  return d.getUTCFullYear()*10000 + (d.getUTCMonth()+1)*100 + d.getUTCDate();
}

/* ─── Streak counter ─── */
function checkStreak(){
  if(typeof G !== 'object') return;
  var today = todayKey();
  if(!G.streak.lastDay){
    G.streak = {count: 1, lastDay: today};
    return;
  }
  if(G.streak.lastDay === today) return; // already counted today
  // Compute days between
  var d = new Date(); var prev = new Date();
  prev.setUTCFullYear(Math.floor(G.streak.lastDay/10000), (Math.floor(G.streak.lastDay/100)%100)-1, G.streak.lastDay%100);
  var dayDiff = Math.round((d - prev) / 86400000);
  if(dayDiff === 1){ G.streak.count++; }
  else if(dayDiff > 1){ G.streak.count = 1; } // streak broken
  G.streak.lastDay = today;
}
function paintStreak(){
  var el = document.getElementById('top-streak-count');
  if(el && G && G.streak){ el.textContent = G.streak.count; el.parentElement.classList.toggle('hot', G.streak.count >= 3); }
}

/* ─── Welcome-back modal (fires once per session if returning after 30min+) ─── */
function maybeShowWelcome(){
  if(typeof G !== 'object' || !G) return;
  var since = Date.now() - (G.lastSeen || Date.now());
  var minutesAway = since / 60000;
  if(minutesAway < 30) return;          // less than 30 minutes — skip
  if(Date.now() - (G.lastWelcome||0) < 5000) return; // already shown this session
  G.lastWelcome = Date.now();
  buildWelcomeOverlay();
  var hours = Math.floor(minutesAway/60), mins = Math.round(minutesAway%60);
  var label = hours > 0 ? (hours + 'h ' + mins + 'm') : (mins + 'm');
  var rows = [];
  /* ── b342: THE RECEIPT IS THE SOURCE, AND IT IS THE ONLY SOURCE ───────────
     Measured on a returning player: this modal showed "While away 8.0h" AND
     "Time away 8h 0m" — the same fact, twice, in different units, from two
     different estimators — and the gains it was ostensibly reporting
     (+1,553 XP · +4 items · +7 gold · 3 kills) WERE NOT IN IT AT ALL. They
     existed only in a toast and on the Home card behind this modal.

     The duplicate came from a second block further down this file that polled
     for `#welcome-rows` and PREPENDED rows built from `calcCatchup()` — a
     third, display-only ESTIMATE of the absence that b214 already had to stop
     from double-granting. That block is deleted; its numbers were a forecast
     of a night that had already been settled, and quoting a forecast next to
     the ledger is how a player learns not to trust either.

     `lastOfflineSummary` is the receipt processOffline (or the server accrual)
     wrote for the absence THIS modal is about. Everything below is read from
     it — the span, the gains, the death, the licence — and nothing is
     inferred. When there is no fresh receipt the modal falls back to the
     clock-derived label and simply says less, which is the honest degradation.
     Glyphs, not emoji: the four this row list used to carry were pre-existing
     Final Directive debt and are cleared here rather than copied forward. */
  var _off = G.lastOfflineSummary;
  var _fresh = !!(_off && _off.at && (Date.now() - _off.at) < 30*60000);
  var _awayMs = _fresh && _off.awayMs > 0 ? _off.awayMs : since;
  var _awayLbl = (function(ms){
    var m = Math.max(0, Math.round(ms/60000));
    if(m < 60) return m + 'm';
    return Math.floor(m/60) + 'h ' + (m%60) + 'm';
  })(_awayMs);
  rows.push({g:'uiHourglass', t: 'Time away', v: _fresh ? _awayLbl : label});
  if(_fresh){
    /* WHAT THE NIGHT ACTUALLY PAID. One row per channel that moved, and none
       at all for a channel that did not — a "+0 gold" row is noise, and a
       missing row for a channel that DID pay is the bug this fixes. */
    if(_off.gainedXp > 0)    rows.push({g:'uiXp',        t:'XP earned',    v:'+' + Number(_off.gainedXp).toLocaleString()});
    if(_off.gainedItems > 0) rows.push({g:'uiChest',     t:'Items found',  v:'+' + Number(_off.gainedItems).toLocaleString()});
    /* `gold` is the atlas key every other gold render site in the game uses
       (HR.amount('gold', …)); uiCoinStack is the gold-FIND modifier icon. Same
       currency, one glyph. */
    if(_off.gainedGold > 0)  rows.push({g:'gold',        t:'Gold earned',  v:'+' + Number(_off.gainedGold).toLocaleString()});
    if(_off.gainedKills > 0) rows.push({g:'uiSword',     t:'Kills',        v:'+' + Number(_off.gainedKills).toLocaleString()});
    if(_off.burnt > 0)       rows.push({g:'uiFire',      t:'Burnt on the fire', v:Number(_off.burnt).toLocaleString()});
    /* b345 — THE RUN THAT STOPPED, on the FIRST screen a returning player
       reads. Same field, same sentence, same span as the Home away card, so
       the two surfaces cannot tell different stories about one absence — the
       exact failure b342 was built to correct. Death keeps its own richer row
       below; this speaks only for the other stop reasons. */
    if(_off.stoppedBy && _off.stoppedBy !== 'death'){
      var _skN = _skillLabel(_off.stoppedSkill);
      rows.push({g:'uiHourglass', bad:true,
        t: _skN + ' ran out of ' + _itemLabel(_off.stoppedById) + ' — nothing was earned after',
        v: fmtSince(_off.paidMs) + ' in'});
    }
  }
  /* b341 — THE FIRST SURFACE A RETURNING PLAYER READS must not put "Time away
     8h 0m" directly above "Total kills 2" and leave the death between them
     unsaid. Reads the SAME receipt the Home card reads (`lastOfflineSummary`),
     stated not inferred, and prints nothing at all when nobody died. */
  try{
    var _dead = _off && (_off.died || (_off.combat && _off.combat.died));
    if(_dead){
      var _ms = Number(_off.diedAfterMs || (_off.combat && _off.combat.survivedMs) || 0);
      var _to = _off.diedTo || (_off.combat && _off.combat.diedTo) || null;
      var _nm = (_to && MONSTERS[_to] && MONSTERS[_to].name) || null;
      var _when = _ms > 0
        ? (_ms < 60000 ? Math.max(1, Math.round(_ms/1000)) + 's in'
                       : Math.floor(_ms/60000) < 60 ? Math.floor(_ms/60000) + 'm in'
                       : Math.floor(_ms/3600000) + 'h in')
        : '—';
      rows.push({g:'uiSkull', bad:true, t: 'You died' + (_nm ? ' to ' + _nm : '') + ' — nothing was earned after', v: _when});
    }
  }catch(e){}
  if(G.streak.count > 0) rows.push({g:'uiFlame', t: 'Daily streak', v: G.streak.count + ' day' + (G.streak.count===1?'':'s')});
  rows.push({g:'uiTarget', t: 'Total kills lifetime', v: (G.stats?.kills||0).toLocaleString()});
  rows.push({g:'gold', t: 'Gold in pocket', v: balText('gold')});
  /* b342: the "bad" tone is now an EXPLICIT flag. It used to key off `r.g`
     (has-a-glyph), which was equivalent only while the death row was the only
     glyph row in the list — the moment the others stopped being emoji, every
     row would have rendered as an alarm. A tone that is a side effect of an
     icon choice is a tone that breaks the next time an icon changes. */
  document.getElementById('welcome-rows').innerHTML = rows.map(function(r){
    var icon = r.g ? _hrGly(r.g, 17) : (r.e || '');
    return '<div class="wb-row'+(r.bad?' wb-row-bad':'')+'"><span class="wb-emoji">'+icon+'</span>'
      +'<span style="flex:1">'+r.t+'</span><b>'+r.v+'</b></div>';
  }).join('');
  var ov = document.getElementById('welcome-overlay');
  if(ov) ov.classList.add('show');
}
/* b341 TEST SEAM, deliberately NOT `window.maybeShowWelcome`.
   This function is not on `window` at all (its block is IIFE-scoped), and the
   welcome-v2 block later does `window.maybeShowWelcome = function(){}` to
   "suppress the old modal" — which suppresses nothing, because the boot already
   captured the lexical reference in `setTimeout(maybeShowWelcome, 1500)` before
   that line ran. So THIS is the modal players actually see on return, and it
   needs to be assertable under a name the dead suppression cannot shadow.
   (The suppression that does not suppress is real debt — flagged, not fixed
   here: deciding which of the two welcome modals survives is a design call.) */
window.__maybeShowWelcome = maybeShowWelcome;
function buildWelcomeOverlay(){
  if(document.getElementById('welcome-overlay')) return;
  var ov = document.createElement('div');
  ov.id = 'welcome-overlay'; ov.className = 'welcome-overlay';
  ov.innerHTML = '<div class="welcome-modal" onclick="event.stopPropagation()">'+
    '<h2>Welcome back, adventurer</h2>'+
    '<div class="wb-time">Your homestead missed you.</div>'+
    '<div class="wb-rewards" id="welcome-rows"></div>'+
    '<button class="wb-claim" onclick="document.getElementById(\'welcome-overlay\').classList.remove(\'show\')">Continue</button>'+
    '</div>';
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.classList.remove('show'); });
  document.body.appendChild(ov);
}

/* ─── Daily Goals (3 quests, refresh per UTC day) ─── */
var DAILY_GOAL_POOL = [
  {id:'kill_any',  emoji:'⚔️', name:'Slay 10 monsters',   target:10, source:'stats.kills'},
  {id:'kill_more', emoji:'🩸', name:'Slay 30 monsters',   target:30, source:'stats.kills'},
  /* b226 (spec §8.2) — these three read PER-SKILL counters, not item-specific
     collection counters. They used to point at collection.normal_log /
     collection.copper_ore / collection.shrimp, so a level-90 woodcutter
     chopping Duskwood made zero progress on "Gather 25 logs" and "Catch 15
     fish" was unachievable for anyone past Shrimp unless they deliberately
     downgraded. A daily that gets harder the better you are is backwards. */
  {id:'gather_logs', emoji:'🪵', name:'Gather 25 logs',  target:25, source:'stats.chopped'},
  {id:'mine_ore',  emoji:'⛏️', name:'Mine 25 ores',      target:25, source:'stats.mined'},
  {id:'cook',      emoji:'🍳', name:'Cook 5 dishes',     target:5,  source:'stats.cooked'},
  {id:'fish',      emoji:'🎣', name:'Catch 15 fish',     target:15, source:'stats.fished'},
  {id:'gold_500',  emoji:'🪙', name:'Earn 500 gold',     target:500, source:'_dailyGoldDelta'},
  {id:'plant',     emoji:'🌾', name:'Plant 5 crops',     target:5,  source:'stats.planted'},
  {id:'level_up',  emoji:'📈', name:'Gain a skill level', target:1,  source:'stats.levelups'},
];
function getGoalsForToday(){
  var key = todayKey();
  if(!G.dailyGoals || G.dailyGoals.dayKey !== key){
    // Pick 3 deterministic goals based on day
    var seed = key;
    var picks = []; var used = {};
    for(var i = 0; i < 3; i++){
      seed = (seed * 9301 + 49297) % 233280;
      var idx = Math.floor((seed/233280) * DAILY_GOAL_POOL.length);
      while(used[idx]) idx = (idx+1) % DAILY_GOAL_POOL.length;
      used[idx] = true; picks.push(DAILY_GOAL_POOL[idx]);
    }
    G.dailyGoals = {dayKey: key, picks: picks.map(function(g){return g.id;}), startValues: {}};
    picks.forEach(function(g){
      G.dailyGoals.startValues[g.id] = readSource(g.source);
    });
  }
  return G.dailyGoals.picks.map(function(id){
    return DAILY_GOAL_POOL.find(function(p){return p.id===id;});
  }).filter(Boolean);
}
// b130: explicit window assignment so the Quests modal renderer in
// the wrapped IIFE below can find it. Same fix pattern as b127's
// hoursTillUTCMidnight — function declarations don't reach window
// from inside nested IIFEs.
window.getGoalsForToday = getGoalsForToday;
/* b226: the pool itself, so the suite can assert what each goal READS. The
   sources are the fix — a goal that watches one item id is the bug. */
window.DAILY_GOAL_POOL = DAILY_GOAL_POOL;

/* b224 (LIVE HOTFIX) — the quests-never-tick bug.
   readSource() is declared INSIDE this IIFE (block 16). The Quests strip +
   modal live in their own IIFE (block 40) and referenced it bare, guarded by
   `if(typeof readSource !== 'function') return 0;`. That guard never threw — it
   just returned 0 — so every daily and weekly quest reported 0 / N forever and
   nothing was ever claimable, with nothing in the console to show for it.
   Exactly the cross-IIFE trap b127 (hoursTillUTCMidnight) and b130
   (getGoalsForToday) already fixed here; readSource was the third read out of
   this scope and the only one whose failure was silent. Export it.
   The smoke suite now asserts a real player counter moves the RENDERED number,
   so an export can never quietly go missing again. */
function readSource(path){
  if(!G) return 0;
  /* `_dailyGoldDelta` is a derived source, not a path into G — without this the
     "Earn 500 gold" daily read G._dailyGoldDelta (undefined → 0) and stayed at
     0 even once the renderer could see it. readPath() (block 17) already
     derives it exactly this way. */
  /* b292: ONE definition of daily gold income — delegate, never re-derive. Three
     copies of this maths existed and the goal read a net-balance one. */
  if(path === '_dailyGoldDelta') return (typeof window._dailyGoldDelta === 'function')
    ? window._dailyGoldDelta()
    : Math.max(0, balOr('gold', 0) - ((G.dailyGoldStart||{}).gold||0));
  var parts = path.split('.');
  var cur = G;
  for(var i = 0; i < parts.length; i++){
    if(cur == null) return 0;
    cur = cur[parts[i]];
  }
  return cur || 0;
}
window.readSource = readSource;
function renderDailyGoals(host){
  if(!host) return;
  var goals = getGoalsForToday();
  host.innerHTML = '<div class="card"><div class="card-head"><div class="card-title">Daily Goals</div><span class="card-sub">Resets at UTC midnight</span></div><div class="card-body"><div class="daily-goals">' +
    goals.map(function(g){
      var startVal = (G.dailyGoals.startValues||{})[g.id] || 0;
      var current = Math.max(0, readSource(g.source) - startVal);
      var done = current >= g.target;
      return '<div class="daily-goal'+(done?' done':'')+'">'+
        '<span class="dg-emoji">'+g.emoji+'</span>'+
        '<div class="dg-text"><b>'+g.name+'</b><span>'+(done?'Complete!':'Resets in ' + hoursTillUTCMidnight() + 'h')+'</span></div>'+
        '<span class="dg-progress">'+Math.min(current,g.target)+' / '+g.target+'</span>'+
      '</div>';
    }).join('') + '</div></div></div>';
}
function hoursTillUTCMidnight(){
  var d = new Date(); return Math.max(1, 24 - d.getUTCHours());
}
// b127: explicit window assignment. Function declarations at the top
// of legacy.js don't always reach `window` from inside the quests-modal
// IIFE, so the renderer fell through to the '?' fallback and rendered
// "Resets in ?h" forever.
window.hoursTillUTCMidnight = hoursTillUTCMidnight;

/* ─── Character page: Combat Stats Breakdown + Equipped Loadout ─── */
window._renderCharacterExtras = function(){
  var host = document.getElementById('panel-character');
  if(!host || !host.querySelector('.char-section')) return;
  if(host.querySelector('.combat-stats-grid')) return; // already added
  var eq = (typeof getEquipmentStats === 'function') ? getEquipmentStats() : {atkB:0,strB:0,defB:0};
  var lvl = (typeof getLevel === 'function') ? getLevel : function(){return 1;};
  var totAtk = lvl('attack')+(eq.atkB||0), totStr = lvl('strength')+(eq.strB||0), totDef = lvl('defense')+(eq.defB||0);
  var combatBlock = '<div class="card char-section">'+
    '<h3>Combat Stats Breakdown</h3>'+
    '<div class="combat-stats-grid">'+
      '<div class="cs-stat"><b>'+totAtk+'</b><span>Attack</span><small>Lv '+lvl('attack')+' + '+(eq.atkB||0)+' gear</small></div>'+
      '<div class="cs-stat"><b>'+totStr+'</b><span>Strength</span><small>Lv '+lvl('strength')+' + '+(eq.strB||0)+' gear</small></div>'+
      '<div class="cs-stat"><b>'+totDef+'</b><span>Defense</span><small>Lv '+lvl('defense')+' + '+(eq.defB||0)+' gear</small></div>'+
      '<div class="cs-stat"><b>'+lvl('hitpoints')+'</b><span>HP</span><small>Max health</small></div>'+
      '<div class="cs-stat"><b>'+lvl('magic')+'</b><span>Magic</span><small>Spell power</small></div>'+
      '<div class="cs-stat"><b>'+lvl('ranged')+'</b><span>Ranged</span><small>Bow accuracy</small></div>'+
      '<div class="cs-stat"><b>'+(eq.weaponType||'sword')+'</b><span>Style</span><small>Active weapon</small></div>'+
      '<div class="cs-stat"><b>'+((eq.critB*100||0).toFixed(0))+'%</b><span>Crit Bonus</span><small>From gear</small></div>'+
    '</div></div>';
  /* Equipped Loadout strip */
  var slots = (typeof EQUIP_SLOTS !== 'undefined') ? EQUIP_SLOTS : [];
  var meta = (typeof EQUIP_SLOT_META !== 'undefined') ? EQUIP_SLOT_META : {};
  var stripCells = slots.map(function(s){
    var id = G.equipment ? G.equipment[s] : null;
    var def = id && (typeof ITEMS!=='undefined') ? ITEMS[id] : null;
    var path = id && window._itemPath && window._itemPath[id];
    if(def && path){
      return '<div class="eq-slot"><img src="'+path+'" alt="" /><small>'+(meta[s]?.label||s).slice(0,3)+'</small></div>';
    }
    return '<div class="eq-slot empty">'+(meta[s]?.icon||'·')+'<small>'+(meta[s]?.label||s).slice(0,3)+'</small></div>';
  }).join('');
  var loadoutBlock = '<div class="card char-section">'+
    '<h3>Equipped Loadout</h3>'+
    '<div class="eq-strip">'+stripCells+'</div></div>';
  host.insertAdjacentHTML('beforeend', combatBlock + loadoutBlock);
};

/* ─── Combat empty-state next-fight suggestion ───
   b362 — RETIRED, AND THE VOID WITH IT. `AWAITING A FOE` was the largest
   element on the combat screen and it was a placeholder: the arena had an idle
   state because the arena shared a screen with the thing that chose its foe.
   The two-screen split (docs/design/combat-screen-rework.md) removes the reason
   for it — the Fight screen cannot be reached without choosing someone, so it
   has no idle state to fill, and "what do I fight next?" is now answered by a
   whole screen (the War Table) instead of by three suggestions duplicating the
   list two columns to their left.

   The function survives as a NO-OP rather than being deleted because it is
   called from a showTab wrapper and from the suite, and a missing global on a
   17k-line engine is a null-render at the worst moment. It bails the instant
   the new screens are up; if they have NOT booted, it still paints the old
   empty state, so a cold load never shows a blank arena. */
window._renderCombatEmpty = function(){
  if(window.HearthriseCombatScreens) return;
  var area = document.getElementById('combat-area');
  if(!area || G.activeMonster) return;
  if(typeof MONSTERS === 'undefined' || typeof getCombatLevel !== 'function') return;
  var cl = getCombatLevel();
  var picks = Object.entries(MONSTERS).map(function(kv){
    var m = kv[1]; var req = (m.tier-1)*15;
    var diff = Math.abs(cl - req - 5); // target slightly above your level
    return {id:kv[0], m:m, diff:diff, unlocked:cl>=req};
  }).filter(function(p){return p.unlocked;}).sort(function(a,b){return a.diff-b.diff;}).slice(0,3);
  if(!picks.length) return;
  // b131: text adapts to layout. On mobile (single column with FOES sub-tab),
  // there is no "left" — monsters are above. Pick the right hint.
  /* b217: this used to render "Pick a monster on the left" over a stack of
     three SUGGESTED monsters — the same Slime / Field Rat / Goblin already
     listed in the picker two columns to the left, on the same screen. Two
     copies of one list is the clearest kind of UI redundancy there is.

     The arena is a stage, so the idle state now shows the champion standing
     on it waiting, plus ONE recommended opponent as a real call to action.
     That gives the largest region on the screen a subject instead of a
     placeholder, and turns "nothing is happening" into "you're up next". */
  var IS = window.HearthriseIconSet;
  var pickHint = (window.innerWidth <= 540) ? 'Choose a foe from FOES.' : 'Choose a foe from the list.';
  var best = picks[0];
  var avatar = (window._playerAvatar || 'assets/icons-bundle/painted/npc/player.png');
  var foeArt = '';
  if (best) {
    var fp = window._monsterIcon && window._monsterIcon[best.id];
    foeArt = fp ? '<img class="ce-foe-art" src="' + fp + '" alt="" />'
                : (IS && IS.medallionMon ? IS.medallionMon(best.id, 46) : '');
  }
  var html = '<div class="combat-empty">' +
    '<div class="ce-stage">' +
      '<img class="ce-champ" src="' + avatar + '" alt="" data-hr-avatar />' +
      '<div class="ce-standby">Awaiting a foe</div>' +
      '<div class="ce-hint">' + pickHint + '</div>' +
    '</div>';
  if (best) {
    /* ── b342: THE FAST PATH MUST NOT SKIP THE ONE HONEST SCREEN ────────────
       This card is the most likely first action in the game — it is the only
       call-to-action on an empty arena, it names the foe, and it says "Fight".
       It carried `onclick="startCombat(id)"`, so one click went straight into
       combat, past the forecast modal that is the ONLY surface telling a new
       player how long they survive and whether the fight pays while away.
       b341 removed exactly that one-tap-to-fight from every monster ROW and
       left it here, which meant the honesty work could be routed around by
       the shortest path through the screen.

       No handler and no third wrapper: it carries `data-monster` and the ONE
       delegated listener on `#panel-combat` (see the b341 block by
       renderPreview) opens the preview, however this card came to be painted.
       The preview's own Fight button is the way into the fight. */
    html += '<button class="ce-next" data-monster="' + best.id + '">' +
      '<span class="ce-next-art">' + foeArt + '</span>' +
      '<span class="ce-next-body">' +
        '<span class="ce-next-lbl">Recommended</span>' +
        '<b>' + best.m.name + '</b>' +
        '<span class="ce-next-meta">Tier ' + best.m.tier + ' · ' + best.m.hp + ' HP · ' + best.m.xp + ' XP</span>' +
      '</span>' +
      '<span class="ce-next-go">Fight</span>' +
    '</button>';
  }
  html += '</div>';
  area.innerHTML = html;
};

/* ─── Inventory total value ───
 * b217: this used to prepend a whole extra header strip to the Inventory panel
 * ("BAG TOTAL VALUE / 95 GP" on the left, "16 items · 3 unique" on the right),
 * sitting above the toolbar that ALSO reported the item count. Two bars, three
 * restatements of the same two facts, ~110px of chrome before the bag.
 * The value is now folded into the single toolbar line the panel already has,
 * which this function keeps up to date after inventory changes. */
window._renderInvSummary = function(){
  var panel = document.getElementById('panel-inventory');
  if(!panel || typeof ITEMS === 'undefined') return;
  var legacyBar = panel.querySelector('.inv-summary');
  if(legacyBar) legacyBar.remove();
  var total = 0, count = 0;
  Object.entries(G.inventory||{}).forEach(function(kv){
    var id = kv[0], qty = kv[1];
    if(!qty || !ITEMS[id]) return;
    total += (typeof vendorPrice==='function' ? vendorPrice(id) : (ITEMS[id].v||0)) * qty;
    count += qty;
  });
  /* b348: write into the SUB-span, never over the whole line. This used to do
     `slot.textContent = ...` on `.invc-space`, which destroyed the "3 / 100
     slots (97 free)" figure renderInvFancy had just written — measured: the
     capacity readout survived ~50ms after every tab entry and was then replaced
     by "16 items · 63 gp". The bank cap is genuinely enforced (addItem refuses
     a new stack at the wall), so the one surface that stated it was being
     erased by a summary updater. Falls back to the old target only if the sub
     span is missing, so an older layout still gets its summary. */
  var sub = panel.querySelector('.invc-space .invc-space-sub');
  var line = ' · ' + count.toLocaleString() + ' items · ' + total.toLocaleString() + ' gp';
  if(sub){ sub.textContent = line; return; }
  var slot = panel.querySelector('.invc-space');
  if(slot) slot.textContent = count.toLocaleString() + ' items · ' + total.toLocaleString() + ' gp';
};

/* ─── Sidebar nav notification badges ─── */
function paintNavBadges(){
  function setBadge(tab, show){
    var btn = document.querySelector('.nav-btn[data-tab="'+tab+'"]');
    if(!btn) return;
    var dot = btn.querySelector('.nav-badge');
    if(!dot){ dot = document.createElement('span'); dot.className='nav-badge'; btn.appendChild(dot); }
    dot.classList.toggle('hide', !show);
  }
  if(typeof G !== 'object' || !G) return;
  // Bounty ready
  var bRdy = !!(G.bountyHunter && G.bountyHunter.active &&
    G.bountyHunter.active.progress >= G.bountyHunter.active.required);
  setBadge('bounty', bRdy);
  // Farm plot ready
  var fRdy = (G.farmPlots||[]).some(function(p){return p && p.state==='ready';});
  setBadge('farming', fRdy);
  // Inventory near full
  var invCount = Object.values(G.inventory||{}).reduce(function(a,b){return a+(b||0);},0);
  setBadge('inventory', invCount > 250);
  // Combat: active fight
  setBadge('combat', !!G.activeMonster);
}

/* ─── Hooks ─── */
function paintAll(){
  paintStreak();
  paintNavBadges();
}
['updateTopbar','renderProfile','renderCombat','renderFarm','renderInvNew','showTab'].forEach(function(name){
  var orig = window[name];
  if(typeof orig !== 'function') return;
  window[name] = function(){
    var r = orig.apply(this, arguments);
    setTimeout(paintAll, 0);
    return r;
  };
});

/* When showTab changes, render appropriate extras */
window.HearthriseShowTab.wrapShowTab('panel-extras', function(tab){
  // b407 flicker fix: paint synchronously in the activating task (was 50ms defer),
  // so the extras appear in the same frame as the panel rather than filling in late.
  if(tab==='character'){ window._renderCharacterExtras(); }
  if(tab==='combat'){ window._renderCombatEmpty(); }
  if(tab==='inventory'){ window._renderInvSummary(); }
  if(tab==='profile'){ injectDailyGoals(); }
  paintAll();
});

function injectDailyGoals(){
  var panel = document.getElementById('panel-profile');
  if(!panel) return;
  var existing = panel.querySelector('.daily-goals');
  if(existing) existing.closest('.card')?.remove();
  var hostId = 'daily-goals-host';
  var host = document.getElementById(hostId);
  if(!host){
    host = document.createElement('div');
    host.id = hostId;
    host.style.gridColumn = '1 / -1';
    panel.insertBefore(host, panel.firstChild);
  }
  renderDailyGoals(host);
}

/* Boot sequence */
function boot(){
  migrate();
  checkStreak();
  setTimeout(maybeShowWelcome, 1500);
  setTimeout(paintAll, 600);
  setTimeout(injectDailyGoals, 800);
  setInterval(paintAll, 4000);   // periodic refresh of badges + streak
}
if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', boot); }
else { setTimeout(boot, 200); }

console.log('UI overhaul loaded');
})();

