/* b229: this array is IIFE-scoped, but the Hero screen's Account panel needs
   ACHIEVEMENTS.length to print "X / total". Publish it read-only (the per-player
   UNLOCK state stays in G.achievements) so the panel counts against the real
   catalogue rather than a hand-copied number. */
window.ACHIEVEMENTS = ACHIEVEMENTS;

function readPath(path){
  if(typeof G !== 'object' || !G) return 0;
  if(path === '_dailyGoldDelta'){
    /* b292: delegate to the single income definition (see _dailyGoldDelta). */
    return (typeof window._dailyGoldDelta === 'function')
      ? window._dailyGoldDelta()
      : Math.max(0, balOr('gold', 0) - ((G.dailyGoldStart||{}).gold||0));
  }
  if(path === 'highest_skill'){
    if(typeof getLevel !== 'function') return 1;
    var max = 0;
    Object.keys(G.skills||{}).forEach(function(k){ var l = getLevel(k); if(l > max) max = l; });
    return max;
  }
  if(path === 'min_combat_skill'){
    if(typeof getLevel !== 'function') return 1;
    var combat = ['attack','strength','defense','hitpoints'];
    var min = Infinity;
    combat.forEach(function(k){ var l = getLevel(k); if(l < min) min = l; });
    return min;
  }
  var parts = path.split('.'); var cur = G;
  for(var i = 0; i < parts.length; i++){ if(cur == null) return 0; cur = cur[parts[i]]; }
  return cur || 0;
}

function checkAchievements(){
  if(typeof G !== 'object' || !G) return;
  G.achievements = G.achievements || {};
  ACHIEVEMENTS.forEach(function(a){
    var entry = G.achievements[a.id] || (G.achievements[a.id] = {progress:0, unlocked:false});
    var cur = readPath(a.src);
    entry.progress = cur;
    if(!entry.unlocked && cur >= a.target){
      entry.unlocked = true;
      entry.unlockedAt = Date.now();
      showAchToast(a);
    }
  });
}
/* showAchToast + openAchievements EXTRACTED to src/render/achievements.js
   (3rd render-layer strangler-fig, task #129). Both are re-exported onto
   window there; checkAchievements above calls window.showAchToast on unlock,
   and the inline onclick="openAchievements()" toolbar handlers resolve to the
   window global. See docs/design/render-extraction-pattern.md. */

/* =========================================================
   2. LEVEL-UP CELEBRATION (wraps addXp)
   ========================================================= */
(function(){
  var orig = window.addXp;
  if(typeof orig !== 'function') return;
  window.addXp = function(sk, amt){
    var before = (typeof G !== 'undefined' && G.skills) ? G.skills[sk] || 0 : 0;
    var lvBefore = (typeof getLevel === 'function') ? getLevel(sk) : 1;
    var r = orig.apply(this, arguments);
    var lvAfter = (typeof getLevel === 'function') ? getLevel(sk) : 1;
    if(lvAfter > lvBefore){
      G.stats = G.stats || {};
      G.stats.levelups = (G.stats.levelups||0) + 1;
      showLevelupCelebration(sk, lvAfter);
    }
    return r;
  };
})();
/* showLevelupCelebration extracted to src/render/levelup-celebration.js (b385,
   render-layer strangler-fig #6). It is a window global; the addXp wrapper above
   calls it by bare name, which resolves to window.showLevelupCelebration. */

/* =========================================================
   3. CATCHUP REWARDS (offline progress)
   ========================================================= */
function calcCatchup(){
  if(typeof G !== 'object' || !G) return null;
  var since = Date.now() - (G.lastSeen || Date.now());
  var hoursAway = since / 3600000;
  if(hoursAway < 0.5) return null;            // <30 min — no catchup
  hoursAway = Math.min(hoursAway, 12);        // cap at 12 hours
  var rewards = {hours: hoursAway, xp: {}, gold: 0};
  if(G.activeSkill && G.skillTargetId){
    var node = null;
    if(typeof TREES !== 'undefined') node = TREES.find(function(a){return a.id===G.skillTargetId;});
    if(!node && typeof ROCKS !== 'undefined') node = ROCKS.find(function(a){return a.id===G.skillTargetId;});
    if(!node && typeof FISH_SPOTS !== 'undefined') node = FISH_SPOTS.find(function(a){return a.id===G.skillTargetId;});
    if(node){
      var aph = 3600000 / Math.max(500, node.ms);
      var actions = Math.floor(hoursAway * aph * 0.5); // 50% efficiency offline
      var xpGain = actions * node.xp;
      rewards.xp[G.activeSkill] = xpGain;
      rewards.itemId = node.prod;
      rewards.itemQty = Math.floor(actions * (node.qty[0]+node.qty[1])/2);
    }
  }
  return rewards;
}
window._catchupCalc = calcCatchup;
window._applyCatchup = function(rewards){
  if(!rewards) return;
  Object.keys(rewards.xp||{}).forEach(function(sk){
    if(typeof addXp === 'function') addXp(sk, rewards.xp[sk]);
  });
  if(rewards.itemId && rewards.itemQty){
    if(typeof addItem === 'function') addItem(rewards.itemId, rewards.itemQty);
  }
};

/* =========================================================
   4. BESTIARY
   ========================================================= */
(function(){
  var orig = window.killMonster;
  if(typeof orig !== 'function') return;
  window.killMonster = function(m){
    if(G.activeMonster){
      G.bestiary = G.bestiary || {};
      var entry = G.bestiary[G.activeMonster] || (G.bestiary[G.activeMonster] = {kills:0, firstKill:0});
      entry.kills++;
      if(!entry.firstKill) entry.firstKill = Date.now();
      var thresholds = [10,50,100,500,1000];
      thresholds.forEach(function(t){ if(entry.kills === t){ if(typeof notify === 'function') notify('🏛️ Bestiary milestone: '+m.name+' × '+t,'levelup'); }});
    }
    return orig.apply(this, arguments);
  };
})();
