/* ─── Artisan render: replaces 'Train by fighting' empty state ─── */
window.renderArtisanActivities = function(skillId){
  var recipes = window.ARTISAN_RECIPES[skillId];
  if(!recipes || typeof getLevel !== 'function') return '';
  var lv = getLevel(skillId);
  return recipes.map(function(r){
    var have = (G.inventory && G.inventory[r.input]) || 0;
    var unlocked = lv >= r.req;
    var canDo = unlocked && have > 0;
    var active = G.activeSkill===skillId && G.skillTargetId===r.id;
    var inputName = (typeof ITEMS!=='undefined' && ITEMS[r.input]) ? ITEMS[r.input].n : r.input;
    var outputLabel = r.output && typeof ITEMS!=='undefined' && ITEMS[r.output] ? ITEMS[r.output].n : (r.output||'XP only');
    var status = '';
    if(!unlocked) status = '<span class="muted tiny">🔒 Lv '+r.req+'</span>';
    else if(!have) status = '<span class="muted tiny">Need '+inputName+'</span>';
    else if(active) status = '<span class="mr-active">Active</span>';
    var secondaryText = '';
    if(r.secondary){
      secondaryText = ' + ' + Object.entries(r.secondary).map(function(kv){
        var nm = (ITEMS[kv[0]]&&ITEMS[kv[0]].n)||kv[0];
        return kv[1]+'×'+nm;
      }).join(', ');
    }
    return '<button class="monster-row '+(active?'fighting':'')+'" '+(canDo?'':'disabled')+' onclick="'+(active?'stopSkill()':"window.startArtisan('"+skillId+"','"+r.id+"')")+'">'+
      '<span class="mi">'+r.icon+'</span>'+
      '<div style="flex:1;min-width:0"><span class="mn">'+r.name+'</span><span class="ms">Lv '+r.req+' · '+Math.max(1,Math.floor(window.pacedXp(skillId,r.xp)))+' XP · '+(window.pacedActionMs(r.ms)/1000).toFixed(1)+'s · ('+inputName+secondaryText+(r.output?' → '+outputLabel:'')+') · Have: '+have+'</span></div>'+
      status+
    '</button>';
  }).join('');
};

/* ─── Artisan action loop (mirrors startSkill but consumes inputs) ─── */
window.startArtisan = function(skillId, recipeId){
  var recipes = window.ARTISAN_RECIPES[skillId];
  if(!recipes) return;
  var r = recipes.find(function(x){return x.id===recipeId;});
  if(!r) return;
  if(getLevel(skillId) < r.req){ if(typeof notify==='function') notify('Need Lv '+r.req+' '+skillId,'kill'); return; }
  if(!(G.inventory[r.input] > 0)){ if(typeof notify==='function') notify('No '+(ITEMS[r.input]?.n||r.input),'kill'); return; }
  /* b348 SEAM 6 — quiet inner stop, one gesture one declaration. */
  if(typeof stopSkill === 'function') activityQuietly(stopSkill);
  G.activeSkill = skillId; G.skillTargetId = recipeId; G.skillProgress = 0;
  G.skillMs = artisanIntervalMs(skillId, r);
  window._armArtisanTimers(G.skillMs);
  if(typeof renderSkillsList==='function') renderSkillsList();
  if(typeof renderSkillDetail==='function') renderSkillDetail(skillId);
  /* DECLARED AS `artisan`, AND SINCE b356 MOST OF THEM ARE SENT AS `artisan`
     TOO — the engine prices 261 of the 290 recipes. The COOKING bench is the
     exception and is still downgraded to `idle`, per RECIPE rather than per
     kind: `noBurn`'s Kitchen rung is read from server state but still written
     by this client, so a server night would burn what the player's Range
     protects. src/net/activity.js's `declarationFor` owns that decision and the
     reason for it; nothing here needs to know which is which, and that is the
     point — when the last bench opens, this line changes not at all. */
  declareActivity('artisan',recipeId);
};

/* b227: ONE place that arms the artisan timers, so retimeActivity() can swap
   the interval mid-session without duplicating the loop bodies — and so the
   two startArtisan definitions in this file (the base one above and the
   inputs-aware override further down) cannot drift apart again. They read
   G.activeSkill / G.skillTargetId rather than closing over arguments, because
   by the time a retime fires those are the authority on what is running. */
window._armArtisanTimers = function(ms){
  if(window._artisanInterval) clearInterval(window._artisanInterval);
  if(window._artisanProgress) clearInterval(window._artisanProgress);
  window._artisanInterval = setInterval(function(){ doArtisanAction(G.activeSkill, G.skillTargetId); }, ms);
  window._artisanProgress = setInterval(function(){
    G.skillProgress = Math.min(1, G.skillProgress + (100/ms));
    if((typeof window.isSkillsVisible==='function' ? window.isSkillsVisible() : (typeof activeTab !== 'undefined' && activeTab==='skills')) && typeof renderSkillDetail==='function') renderSkillDetail(G.activeSkill);
  }, 100);
};
/* b201: each artisan skill reads its own workbench-room speed bonus. Routed
   through the shared activityIntervalMs() so the live loop, the retimer and
   the offline replay all compute the identical number from one formula. */
function artisanIntervalMs(skillId, r){
  var ms = (typeof window.activityIntervalMs === 'function') ? window.activityIntervalMs() : null;
  if(ms != null) return ms;
  var bonusKey = window.speedKeyFor(skillId);
  var speed = (typeof getBonus==='function') ? getBonus(bonusKey) : 0;
  return Math.max(500, Math.floor(window.pacedActionMs(r.ms) * (1 - speed)));
}

window.doArtisanAction = function(skillId, recipeId){
  var recipes = window.ARTISAN_RECIPES[skillId];
  var r = recipes && recipes.find(function(x){return x.id===recipeId;});
  if(!r) return;
  /* Out of input or secondary? Stop. */
  if(!(G.inventory[r.input] > 0)){ window._stopArtisan(); return; }
  if(r.secondary){
    var oot = false;
    Object.entries(r.secondary).forEach(function(kv){ if((G.inventory[kv[0]]||0) < kv[1]) oot = true; });
    if(oot){ window._stopArtisan(); if(typeof notify==='function') notify('Out of secondary materials','kill'); return; }
  }
  /* Consume */
  if(typeof removeItem==='function') removeItem(r.input, 1);
  if(r.secondary) Object.entries(r.secondary).forEach(function(kv){ removeItem(kv[0], kv[1]); });
  /* Produce */
  if(r.output && typeof addItem==='function') addItem(r.output, 1);
  /* XP */
  if(typeof addXp==='function') addXp(skillId, r.xp);
  /* Counters */
  if(skillId==='cooking'){
    G.stats.cooked = (G.stats.cooked||0) + 1;
    if(typeof updateDaily==='function') updateDaily('cooked', 1);
    // b217: onboarding chain routes new players through cooking BEFORE combat
    // (the "Cook 5 dishes" prep quest), so mirror the counter into updateQuest.
    if(typeof updateQuest==='function') updateQuest('cooked', 1);
  }
  if(skillId==='smithing'){
    G.stats.refined = (G.stats.refined||0) + 1;
    G.stats.smithed = (G.stats.smithed||0) + 1;
    if(typeof updateDaily==='function') updateDaily('smithed', 1);
  }
  if(skillId==='crafting'){
    G.stats.refined = (G.stats.refined||0) + 1;
    G.stats.crafted = (G.stats.crafted||0) + 1;
    if(typeof updateDaily==='function') updateDaily('crafted', 1);
  }
  if(typeof renderSkillDetail==='function') renderSkillDetail(skillId);
  if(typeof updateTopbar==='function') updateTopbar();
};

/* Hook into existing stopSkill so we also clear artisan intervals */
window._stopArtisan = function(){
  if(window._artisanInterval){ clearInterval(window._artisanInterval); window._artisanInterval=null; }
  if(window._artisanProgress){ clearInterval(window._artisanProgress); window._artisanProgress=null; }
};
(function(){
  var origStop = window.stopSkill;
  if(typeof origStop !== 'function') return;
  window.stopSkill = function(){
    window._stopArtisan();
    return origStop.apply(this, arguments);
  };
})();

/* ─── Daily gold-today tracking ─── */
(function(){
  if(typeof G !== 'object' || !G) return;
  function todayKey(){ var d=new Date(); return d.getUTCFullYear()*10000+(d.getUTCMonth()+1)*100+d.getUTCDate(); }
  function checkDailyGold(){
    if(typeof G !== 'object') return;
    var today = todayKey();
    /* ⚠ THE BASELINE MUST NOT BE TAKEN AGAINST AN UNKNOWN BALANCE. `G.gold||0`
       here recorded a day-start of ZERO for a client that had simply not been
       told the balance yet — and the net-balance fallback below then reads the
       first envelope's 500,000 as "earned today", completing the "Earn 500
       gold" daily the instant the player connects. A baseline nobody can
       measure is not taken at all; the next tick (60s) takes it once the
       number lands. */
    if(!balKnown('gold')) return;
    if(!G.dailyGoldStart || G.dailyGoldStart.day !== today){
      G.dailyGoldStart = {day: today, gold: balNum('gold'), earned: 0};
    }
    if(typeof G.dailyGoldStart.earned !== 'number') G.dailyGoldStart.earned = 0;
  }
  setTimeout(checkDailyGold, 200);
  setInterval(checkDailyGold, 60000);

  /* b292 (paione: "I sold about 10k in items didn't get the quest to earn 500 gold").
     "Earn 500 gold" measured `G.gold - goldAtDayStart` — a NET BALANCE delta, not
     income. Sell 10,000g and then spend it (gear, bank space, seeds) and your net is
     flat, so the quest paid nothing even though you plainly earned the gold. Gold is
     added from eight different places, so instead of touching every call site we
     accumulate only the POSITIVE changes — real income, from any source, and spending
     can never claw it back. */
  var _goldSeen = null;
  setInterval(function(){
    if(typeof G !== 'object' || !G) return;
    /* ⚠ AND THE SAME TRAP ON THE POLLER. `G.gold||0` made an UNKNOWN balance
       read as 0, so the arrival of the first envelope looked like income of the
       player's ENTIRE fortune. UNKNOWN drops the watermark instead: the next
       tick re-seeds it and the arrival is a re-seed, not a gain. */
    var g = balNum('gold');
    if(g === null){ _goldSeen = null; return; }
    if(_goldSeen === null){ _goldSeen = g; return; }
    if(g > _goldSeen){
      checkDailyGold();
      if(G.dailyGoldStart) G.dailyGoldStart.earned = (G.dailyGoldStart.earned || 0) + (g - _goldSeen);
    }
    _goldSeen = g;
  }, 500);
})();

// ===== block 19: goldfix-js =====
(function(){
  var origRead = window.readPath;
  window._dailyGoldDelta = function(){
    if(!G || !G.dailyGoldStart) return 0;
    /* b292: prefer REAL income (accumulated positive gold changes) over the old
       net-balance delta, so selling then spending still counts. Falls back to the
       old maths for a save that predates the counter. */
    var earned = G.dailyGoldStart.earned;
    if(typeof earned === 'number') return Math.max(0, earned);
    return Math.max(0, balOr('gold', 0) - (G.dailyGoldStart.gold||0));
  };
})();

// ===== block 20: welcome-v2-js =====
(function(){
"use strict";

/* ─── Rich catchup calculation ──────────────────────────── */
function calcRichCatchup(){
  if(typeof G !== 'object' || !G) return null;
  var since = Date.now() - (G.lastSeen || Date.now());
  var hoursAway = since / 3600000;
  if(hoursAway < 0.5) return null;
  var capped = Math.min(hoursAway, 12);
  var summary = {
    hoursAway: hoursAway,
    cappedHours: capped,
    xp: {},
    itemsGained: {},
    itemsLost: {},
    gold: 0,
    activities: []
  };
  /* Active gathering skill */
  if(G.activeSkill && G.skillTargetId){
    var node = null;
    if(typeof TREES !== 'undefined') node = TREES.find(function(a){return a.id===G.skillTargetId;});
    if(!node && typeof ROCKS !== 'undefined') node = ROCKS.find(function(a){return a.id===G.skillTargetId;});
    if(!node && typeof FISH_SPOTS !== 'undefined') node = FISH_SPOTS.find(function(a){return a.id===G.skillTargetId;});
    if(node){
      var aph = 3600000 / Math.max(500, node.ms);
      var actions = Math.floor(capped * aph * 0.5);
      var xpGain = Math.floor(actions * node.xp);
      var avgQ = (node.qty[0]+node.qty[1])/2;
      var itemQty = Math.floor(actions * avgQ);
      summary.xp[G.activeSkill] = xpGain;
      summary.itemsGained[node.prod] = itemQty;
      summary.activities.push({
        type: G.activeSkill, label: node.name + ' (×' + actions + ' actions)',
        emoji: node.icon || '⛏️'
      });
    }
  }
  /* Farm plots that finished while away.
     b220: reads the same HearthriseFarm.isReady() the live tick does — one
     source of truth for growth. The old copy re-derived it here AND carried
     `&& p.watered`, so a dry plot was never counted as ready offline either.
     Farm growth is deliberately NOT subject to the 12h offline cap: crops
     mature off plantedAt however long you were away. */
  if(typeof G.farmPlots !== 'undefined' && G.farmPlots){
    var readyPlots = 0, soonPlots = 0;
    var FA = window.HearthriseFarm;
    G.farmPlots.forEach(function(p){
      if(!p) return;
      var crop = (typeof CROPS !== 'undefined') ? CROPS[p.cropId] : null;
      if(!crop) return;
      if(FA && FA.isReady(p)){ readyPlots++; return; }
      if(FA && FA.readyInMs(p) <= 3600000) soonPlots++;
    });
    if(readyPlots > 0){
      summary.activities.push({
        type:'farming',
        label: readyPlots + ' farm plot' + (readyPlots>1?'s':'') + ' ready to harvest'
               + (soonPlots > 0 ? ' · ' + soonPlots + ' more within the hour' : ''),
        emoji:'🌾', readyPlots: readyPlots
      });
    } else if(soonPlots > 0){
      summary.activities.push({
        type:'farming', label: soonPlots + ' farm plot' + (soonPlots>1?'s':'') + ' ready within the hour',
        emoji:'🌾', readyPlots: 0
      });
    }
  }
  /* Bounty progress reminders */
  if(G.bountyHunter && G.bountyHunter.active){
    var bh = G.bountyHunter.active;
    if(bh.progress < bh.required){
      summary.activities.push({
        type:'bounty', label:'Bounty in progress: ' + (bh.progress||0) + ' / ' + bh.required,
        emoji:'🎯'
      });
    } else {
      summary.activities.push({
        type:'bounty', label:'Bounty ready to turn in!',
        emoji:'🎯', ready: true
      });
    }
  }
  return summary;
}
window._calcRichCatchup = calcRichCatchup;

/* Apply gathered XP/items (same effect as before) */
function applyRichCatchup(s){
  if(!s) return;
  Object.keys(s.xp||{}).forEach(function(sk){
    if(typeof addXp === 'function') addXp(sk, s.xp[sk]);
  });
  Object.keys(s.itemsGained||{}).forEach(function(id){
    if(typeof addItem === 'function') addItem(id, s.itemsGained[id]);
  });
}

/* ─── Render the new modal ──────────────────────────────── */
function buildOverlay(){
  if(document.getElementById('wbv-overlay')) return;
  var ov = document.createElement('div');
  ov.id = 'wbv-overlay';
  ov.className = 'wbv-overlay';
  ov.innerHTML = '<div class="wbv-modal" id="wbv-modal" onclick="event.stopPropagation()"></div>';
  ov.addEventListener('click', function(e){ if(e.target===ov) closeModal(); });
  document.body.appendChild(ov);
}
function closeModal(){
  var ov = document.getElementById('wbv-overlay');
  if(ov) ov.classList.remove('show');
}
window._closeWelcomeV2 = closeModal;

function fmtTime(hours){
  var h = Math.floor(hours), m = Math.round((hours-h)*60);
  if(h > 0) return h + 'h ' + m + 'm';
  return m + 'm';
}
function fmtNum(n){
  if(n >= 1000000) return (n/1000000).toFixed(1)+'M';
  if(n >= 1000) return (n/1000).toFixed(1)+'k';
  return Math.floor(n).toLocaleString();
}
function itemImg(id){
  var path = window._itemPath && window._itemPath[id];
  if(path){
    var tint = (typeof window.itemTintClass === 'function') ? window.itemTintClass(id) : '';
    return '<img src="'+path+'" class="wbr-img '+tint+'" alt="" />';
  }
  return '<span class="wbr-emoji">'+itemFallbackIcon(id, 24)+'</span>';
}
function itemName(id){
  return (typeof ITEMS!=='undefined' && ITEMS[id]) ? ITEMS[id].n : id;
}
function skillName(sk){
  return (typeof SKILLS_DEF!=='undefined' && SKILLS_DEF[sk]) ? SKILLS_DEF[sk].name : sk;
}
function skillIcon(sk){
  if(window._skillIcon && window._skillIcon[sk]) return '<img src="'+window._skillIcon[sk]+'" class="wbr-img" alt="" />';
  var med = window.HearthriseIconSet && window.HearthriseIconSet.medallion && window.HearthriseIconSet.medallion(sk, 26);
  return med || '<span class="hr-blank-icon" aria-hidden="true"></span>';
}

function renderModal(summary){
  buildOverlay();
  var modal = document.getElementById('wbv-modal');
  if(!modal) return;
  var streakCount = (G.streak && G.streak.count) || 1;
  var totalKills = (G.stats && G.stats.kills) || 0;

  var sections = '';

  /* XP Section */
  var xpKeys = Object.keys(summary.xp||{}).filter(function(k){return summary.xp[k]>0;});
  var xpTotal = xpKeys.reduce(function(a,k){return a+summary.xp[k];},0);
  if(xpKeys.length){
    sections += '<div class="wbv-section open"><div class="wbv-section-head" onclick="this.parentElement.classList.toggle(\'open\')">'+
      '<span class="wbs-icon">⭐</span>'+
      '<span class="wbs-title">XP Gained</span>'+
      '<span class="wbs-summary">+'+fmtNum(xpTotal)+'</span>'+
      '<span class="wbs-arrow">▶</span></div>'+
      '<div class="wbv-section-body">'+
      xpKeys.map(function(sk){
        return '<div class="wbv-row gain">'+skillIcon(sk)+'<span class="wbr-text">'+skillName(sk)+'</span><span class="wbr-val">+'+fmtNum(summary.xp[sk])+'</span></div>';
      }).join('') +
      '</div></div>';
  }

  /* Items gained */
  var gainKeys = Object.keys(summary.itemsGained||{}).filter(function(k){return summary.itemsGained[k]>0;});
  if(gainKeys.length){
    var totalGained = gainKeys.reduce(function(a,k){return a+summary.itemsGained[k];},0);
    sections += '<div class="wbv-section"><div class="wbv-section-head" onclick="this.parentElement.classList.toggle(\'open\')">'+
      '<span class="wbs-icon">📦</span>'+
      '<span class="wbs-title">Items Gathered</span>'+
      '<span class="wbs-summary">+'+totalGained+' items</span>'+
      '<span class="wbs-arrow">▶</span></div>'+
      '<div class="wbv-section-body">'+
      gainKeys.map(function(id){
        return '<div class="wbv-row gain">'+itemImg(id)+'<span class="wbr-text">'+itemName(id)+'</span><span class="wbr-val">+'+summary.itemsGained[id]+'</span></div>';
      }).join('') +
      '</div></div>';
  }

  /* Items consumed (placeholder — combat catchup coming in Phase 2) */
  var lossKeys = Object.keys(summary.itemsLost||{}).filter(function(k){return summary.itemsLost[k]>0;});
  if(lossKeys.length){
    sections += '<div class="wbv-section"><div class="wbv-section-head" onclick="this.parentElement.classList.toggle(\'open\')">'+
      '<span class="wbs-icon">🍖</span>'+
      '<span class="wbs-title">Items Consumed</span>'+
      '<span class="wbs-summary">-'+lossKeys.length+' types</span>'+
      '<span class="wbs-arrow">▶</span></div>'+
      '<div class="wbv-section-body">'+
      lossKeys.map(function(id){
        return '<div class="wbv-row loss">'+itemImg(id)+'<span class="wbr-text">'+itemName(id)+'</span><span class="wbr-val">-'+summary.itemsLost[id]+'</span></div>';
      }).join('') +
      '</div></div>';
  }

  /* Activities awaiting */
  var awaiting = (summary.activities||[]).filter(function(a){return a.ready||a.readyPlots;});
  if(awaiting.length){
    sections += '<div class="wbv-section open"><div class="wbv-section-head" onclick="this.parentElement.classList.toggle(\'open\')">'+
      '<span class="wbs-icon">🔔</span>'+
      '<span class="wbs-title">Awaiting Your Attention</span>'+
      '<span class="wbs-summary">'+awaiting.length+'</span>'+
      '<span class="wbs-arrow">▶</span></div>'+
      '<div class="wbv-section-body">'+
      awaiting.map(function(a){
        return '<div class="wbv-row"><span class="wbr-emoji">'+a.emoji+'</span><span class="wbr-text">'+a.label+'</span></div>';
      }).join('') +
      '</div></div>';
  }

  /* Active session continuing */
  var ongoing = (summary.activities||[]).filter(function(a){return !a.ready && !a.readyPlots;});
  if(ongoing.length){
    sections += '<div class="wbv-section"><div class="wbv-section-head" onclick="this.parentElement.classList.toggle(\'open\')">'+
      '<span class="wbs-icon">⏳</span>'+
      '<span class="wbs-title">Continuing Activity</span>'+
      '<span class="wbs-summary">'+ongoing.length+'</span>'+
      '<span class="wbs-arrow">▶</span></div>'+
      '<div class="wbv-section-body">'+
      ongoing.map(function(a){
        return '<div class="wbv-row"><span class="wbr-emoji">'+a.emoji+'</span><span class="wbr-text">'+a.label+'</span></div>';
      }).join('') +
      '</div></div>';
  }

  if(!sections){
    sections = '<div class="wbv-empty" style="text-align:center;padding:14px">No active progress while away. Pick a skill to start training!</div>';
  }

  modal.innerHTML =
    '<h2>Welcome back, adventurer</h2>'+
    '<div class="wbv-sub">Your homestead missed you.</div>'+
    '<div class="wbv-statrow">'+
      '<div class="wbv-stat"><b>'+fmtTime(summary.hoursAway)+'</b><span>Time away</span></div>'+
      '<div class="wbv-stat"><b>'+streakCount+'</b><span>Day streak</span></div>'+
      '<div class="wbv-stat"><b>'+balMarkup('gold',{format:fmtNum})+'</b><span>Gold pouch</span></div>'+
    '</div>'+
    sections +
    '<button class="wbv-claim" onclick="window._closeWelcomeV2()">Continue</button>';

  document.getElementById('wbv-overlay').classList.add('show');
}
window._renderWelcomeV2 = renderModal;

/* ─── Replace the boot path: don't show old modal, show v2 ─── */
(function(){
  /* Intercept the old maybeShowWelcome flow */
  var origMaybe = window.maybeShowWelcome;
  if(typeof origMaybe === 'function'){
    window.maybeShowWelcome = function(){ /* suppress old modal */ };
  }
  /* Run our own check on boot */
  setTimeout(function(){
    if(typeof G !== 'object' || !G) return;
    if(Date.now() - (G.lastWelcome||0) < 5000) return; // already shown
    var s = calcRichCatchup();
    if(!s) return;
    G.lastWelcome = Date.now();
    G.lastSessionSummary = s;
    /* b214 (correctness fix): display-only — see the note by calcCatchup's
       caller above. processOffline() already granted; this second grant was
       double-paying every returning gatherer. renderModal shows the estimate. */
    renderModal(s);
  }, 1800);
})();

/* ─── Profile button: re-open last summary ──────────────── */
function injectProfileButton(){
  var panel = document.getElementById('panel-profile');
  if(!panel) return;
  if(panel.querySelector('.wbv-reopen-btn')) return;
  var btn = document.createElement('button');
  btn.className = 'btn wbv-reopen-btn';
  btn.style.cssText = 'margin-left:8px';
  btn.textContent = '📜 Last Session Summary';
  btn.addEventListener('click', function(){
    if(G.lastSessionSummary){ renderModal(G.lastSessionSummary); }
    else if(typeof notify === 'function') notify('No previous session summary yet','info');
  });
  /* Insert into the existing feat-buttons row if present */
  var row = panel.querySelector('.feat-buttons');
  if(row) row.appendChild(btn);
}
setTimeout(injectProfileButton, 800);
window.HearthriseShowTab.wrapShowTab('profile-button', function(t){
  // b407 flicker fix: inject synchronously in the activating task (was 50ms defer).
  if(t === 'profile') injectProfileButton();
});

console.log('Welcome v2 loaded');
})();

