/* ═══ Inventory page: 2-col layout with Tibia doll on the left ═══ */
function patchInventoryPage(){
  var panel = document.getElementById('panel-inventory');
  if(!panel) return;
  /* b216: the modern inventory layout renders its own doll into
     #invc-doll-host. This older top-of-panel host then rendered a SECOND one,
     so the panel carried two complete dolls (28 slots for 14, and after the
     b216 tab work, two sets of Equipment/Stats/Companion tabs). If the modern
     host is present it owns the doll — bail out. */
  if(panel.querySelector('#invc-doll-host')){
    var stale = panel.querySelector('.inv-tibia-host');
    if(stale) stale.remove();
    return;
  }
  /* Hide the old paper-doll if still present from prior renders */
  panel.querySelectorAll('.inv-doll, .loadout-doll').forEach(function(el){ el.style.display='none'; });
  /* Find or create the inline Tibia host */
  var host = panel.querySelector('.inv-tibia-host');
  if(!host){
    host = document.createElement('div');
    host.className = 'inv-tibia-host';
    /* Insert at the very top of the panel */
    panel.insertBefore(host, panel.firstChild);
  }
  /* Refresh the doll inside the host */
  host.innerHTML = '<div style="display:flex;flex-direction:column;align-items:center;gap:4px"><h4>Equipment</h4></div>';
  var inner = host.firstChild;
  var doll = window.buildTibiaDoll();
  if(doll) inner.appendChild(doll);
}

/* ═══ Skills page: allow viewing other skills while one is active ═══ */
function patchSkillsViewing(){
  /* The default openSkillDetail probably calls renderSkillDetail.
     We don't need to change the active state, just allow rendering arbitrary skill detail. */
  var origOpen = window.openSkillDetail;
  if(typeof origOpen !== 'function') return;
  window.openSkillDetail = function(id){
    /* Always show the detail for the clicked skill, regardless of active */
    G.viewingSkill = id;
    var r = origOpen.apply(this, arguments);
    setTimeout(function(){
      var detail = document.getElementById('skill-detail');
      if(!detail) return;
      /* If the viewed skill is NOT the active skill, prepend a "viewing" banner */
      if(G.activeSkill && G.activeSkill !== id){
        var existing = detail.querySelector('.skill-viewing-banner');
        if(existing) existing.remove();
        var sk = (typeof SKILLS_DEF!=='undefined') ? SKILLS_DEF[G.activeSkill] : null;
        var banner = document.createElement('div');
        banner.className = 'skill-viewing-banner';
        banner.innerHTML = '<span>👁️</span><span>You are viewing this skill while training <b>'+(sk?sk.name:G.activeSkill)+'</b>. Click "Stop" on that skill first to start a new activity.</span>';
        detail.insertBefore(banner, detail.firstChild);
      }
    }, 30);
    return r;
  };
}

